import 'headers.dart';

sealed class Address {}

class Mailbox extends Address {
  final String name;
  final String address;
  Mailbox(this.name, this.address);
}

class Group extends Address {
  final List<Mailbox> mailboxes;
  Group(this.mailboxes);
}

bool dotAtom(List<Token> tokens) {
  if (tokens.length.isEven) return false;
  for (var i = 0; i < tokens.length; i++) {
    if (tokens[i].kind != (i.isEven ? 'word' : '.')) return false;
  }
  return true;
}

class AddressParser {
  final List<Token> tokens;
  var position = 0;
  var encodingError = false;
  var failed = false;
  AddressParser(this.tokens);

  String get peek => position < tokens.length ? tokens[position].kind : '';

  void expect(String kind) {
    if (peek != kind) {
      failed = true;
    } else {
      position++;
    }
  }

  List<Token> run(bool phrase) {
    final start = position;
    while (peek == 'word' || peek == '.' || phrase && peek == 'quoted') {
      position++;
    }
    return tokens.sublist(start, position);
  }

  String displayName(List<Token> phrase) {
    final output = StringBuffer();
    var previous = false;
    for (var i = 0; i < phrase.length; i++) {
      final token = phrase[i];
      var text = token.text;
      var decoded = false;
      if (token.kind == 'word') {
        final result = decodeWord(text);
        text = result.$1;
        decoded = result.$2;
        encodingError = encodingError || result.$3;
      }
      if (i > 0 && token.spaced && !(decoded && previous)) output.write(' ');
      output.write(text);
      previous = decoded;
    }
    return collapseWhitespace(output.toString());
  }

  Mailbox? mailbox(List<Token> phrase, List<Token> local,
      List<Token> domain, bool named) {
    if (!dotAtom(local) || !dotAtom(domain)) {
      failed = true;
      return null;
    }
    final text = '${local.map((t) => t.text).join()}@'
        '${domain.map((t) => t.text).join()}';
    return Mailbox(named ? displayName(phrase) : '', text.toLowerCase());
  }

  Address? address(bool inGroup) {
    final phrase = run(true);
    if (peek == '<') {
      position++;
      final local = run(false);
      expect('@');
      final domain = run(false);
      expect('>');
      return mailbox(phrase, local, domain, true);
    }
    if (peek == '@') {
      position++;
      final domain = run(false);
      return mailbox([], phrase, domain, false);
    }
    if (peek == ':' && phrase.isNotEmpty && !inGroup) {
      position++;
      final mailboxes = <Mailbox>[];
      if (peek != ';') {
        while (true) {
          final entry = address(true);
          if (failed || entry is! Mailbox) {
            failed = true;
            return null;
          }
          mailboxes.add(entry);
          if (peek != ',') break;
          position++;
        }
      }
      expect(';');
      return Group(mailboxes);
    }
    failed = true;
    return null;
  }
}

(List<Address>, bool)? parseAddressList(String value) {
  final tokens = tokenize(value, false);
  if (tokens == null || tokens.isEmpty) return null;
  final parser = AddressParser(tokens);
  final addresses = <Address>[];
  while (true) {
    final address = parser.address(false);
    if (parser.failed || address == null) return null;
    addresses.add(address);
    if (parser.peek != ',') break;
    parser.position++;
  }
  if (parser.position != tokens.length) return null;
  return (addresses, parser.encodingError);
}

import 'headers.dart';

const weekdays = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];
const months = [
  'jan', 'feb', 'mar', 'apr', 'may', 'jun',
  'jul', 'aug', 'sep', 'oct', 'nov', 'dec'
];
const namedZones = {
  'ut': 0, 'gmt': 0, 'z': 0, 'est': -300, 'edt': -240, 'cst': -360,
  'cdt': -300, 'mst': -420, 'mdt': -360, 'pst': -480, 'pdt': -420
};

bool leap(int year) => year % 4 == 0 && year % 100 != 0 || year % 400 == 0;
int yearDays(int year) => leap(year) ? 366 : 365;
int monthDays(int year, int month) {
  if (month == 2 && leap(year)) return 29;
  return [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1];
}

bool digits(String text, List<int> lengths) =>
    lengths.contains(text.length) && RegExp(r'^[0-9]+$').hasMatch(text);

(int?, String) parseDate(String value) {
  final text = removeComments(value);
  if (text == null) return (null, 'bad Date syntax');
  var tokens = splitWords(text.replaceAll(',', ' , '));
  var weekday = -1;
  if (tokens.length >= 3 && tokens[1] == ',') {
    weekday = weekdays.indexOf(tokens[0].toLowerCase());
    if (weekday >= 0) tokens = tokens.sublist(2);
  }
  if (tokens.length != 5) return (null, 'bad Date syntax');
  final pieces = tokens[3].split(':');
  final month = months.indexOf(tokens[1].toLowerCase()) + 1;
  final zone = tokens[4];
  final numericZone = zone.length == 5 &&
      (zone[0] == '+' || zone[0] == '-') && digits(zone.substring(1), [4]);
  var offset = namedZones[zone.toLowerCase()];
  if (!digits(tokens[0], [1, 2]) || month == 0 ||
      !digits(tokens[2], [2, 4]) || pieces.length < 2 || pieces.length > 3 ||
      pieces.any((piece) => !digits(piece, [2])) ||
      !(numericZone || offset != null)) {
    return (null, 'bad Date syntax');
  }
  final day = int.parse(tokens[0]);
  var year = int.parse(tokens[2]);
  if (tokens[2].length == 2) year += year < 50 ? 2000 : 1900;
  final hour = int.parse(pieces[0]);
  final minute = int.parse(pieces[1]);
  final second = pieces.length == 3 ? int.parse(pieces[2]) : 0;
  if (numericZone) {
    final hh = int.parse(zone.substring(1, 3));
    final mm = int.parse(zone.substring(3, 5));
    if (hh > 23 || mm > 59) return (null, 'Date out of range');
    offset = (hh * 60 + mm) * (zone[0] == '-' ? -1 : 1);
  }
  if (year < 1970 || year > 2099 || day < 1 ||
      day > monthDays(year, month) || hour > 23 || minute > 59 || second > 59) {
    return (null, 'Date out of range');
  }
  var days = 0;
  for (var current = 1970; current < year; current++) {
    days += yearDays(current);
  }
  for (var current = 1; current < month; current++) {
    days += monthDays(year, current);
  }
  days += day - 1;
  final seconds = days * 86400 + hour * 3600 + minute * 60 + second - offset! * 60;
  if (seconds < 0) return (null, 'Date out of range');
  if (weekday >= 0 && (days + 3) % 7 != weekday) {
    return (null, 'Date weekday mismatch');
  }
  return (seconds, '');
}

String formatUTC(int seconds) {
  var days = seconds ~/ 86400;
  final rest = seconds % 86400;
  var year = 1970;
  while (days >= yearDays(year)) {
    days -= yearDays(year);
    year++;
  }
  var month = 1;
  while (days >= monthDays(year, month)) {
    days -= monthDays(year, month);
    month++;
  }
  String pad(int value, int width) => value.toString().padLeft(width, '0');
  return '${pad(year, 4)}-${pad(month, 2)}-${pad(days + 1, 2)} '
      '${pad(rest ~/ 3600, 2)}:${pad((rest % 3600) ~/ 60, 2)}:${pad(rest % 60, 2)}';
}

import 'mime.dart';

const whitespace = ' \t';
const addressSpecials = '<>:;@,.';
const addressWordChars =
    r"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$%&'*+-/=?^_`{|}~";
const mimeExcluded = '()<>@,;:\\"/[]?=';

class MailLine {
  final int number;
  final String text;
  MailLine(this.number, this.text);
}

class Field {
  final String name;
  String value;
  Field(this.name, this.value);
}

class Header {
  final fields = <Field>[];
  final invalid = <int>[];

  String? value(String name) {
    name = name.toLowerCase();
    for (final field in fields) {
      if (field.name == name) return field.value;
    }
    return null;
  }

  int count(String name) =>
      fields.where((field) => field.name == name.toLowerCase()).length;
}

class Token {
  final String kind;
  final String text;
  final bool spaced;
  Token(this.kind, this.text, this.spaced);
}

class Parameters {
  final String mainType;
  final String subtype;
  final Map<String, String> values;
  Parameters(this.mainType, this.subtype, this.values);
}

List<String> splitWords(String text) =>
    text.split(RegExp(r'[ \t]+')).where((word) => word.isNotEmpty).toList();
String collapseWhitespace(String text) => splitWords(text).join(' ');
String stripWhitespace(String text) =>
    text.replaceFirst(RegExp(r'^[ \t]+'), '').replaceFirst(RegExp(r'[ \t]+$'), '');
String stripTrailing(String text) =>
    text.replaceFirst(RegExp(r'[ \t]+$'), '');

Header parseFields(List<MailLine> lines) {
  final header = Header();
  var inField = false;
  for (final line in lines) {
    final text = line.text;
    if (text.isNotEmpty && whitespace.contains(text[0])) {
      if (inField) {
        header.fields.last.value += text;
      } else {
        header.invalid.add(line.number);
      }
      continue;
    }
    final colon = text.indexOf(':');
    inField = colon > 0 &&
        text.substring(0, colon).codeUnits.every((c) => c >= 33 && c <= 126);
    if (inField) {
      header.fields.add(Field(
          text.substring(0, colon).toLowerCase(), text.substring(colon + 1)));
    } else {
      header.invalid.add(line.number);
    }
  }
  for (final field in header.fields) {
    field.value = stripWhitespace(field.value);
  }
  return header;
}

String? removeComments(String text) {
  final output = StringBuffer();
  var depth = 0;
  for (var position = 0; position < text.length; position++) {
    final c = text[position];
    if (depth == 0) {
      if (c == '(') {
        depth = 1;
        output.write(' ');
      } else {
        output.write(c);
      }
    } else if (c == '\\') {
      position++;
    } else if (c == '(') {
      depth++;
    } else if (c == ')') {
      depth--;
    }
  }
  return depth == 0 ? output.toString() : null;
}

List<Token>? tokenize(String text, bool mime) {
  final tokens = <Token>[];
  var position = 0;
  var spaced = false;
  final specials = mime ? '/;=' : addressSpecials;
  bool isWord(String c) => mime
      ? c.codeUnitAt(0) >= 33 &&
          c.codeUnitAt(0) <= 126 &&
          !mimeExcluded.contains(c)
      : addressWordChars.contains(c);
  while (position < text.length) {
    var c = text[position];
    if (whitespace.contains(c)) {
      spaced = true;
      position++;
      continue;
    }
    if (c == '(') {
      var depth = 1;
      position++;
      while (position < text.length && depth > 0) {
        c = text[position];
        if (c == '\\') {
          position += 2;
          continue;
        }
        if (c == '(') depth++;
        if (c == ')') depth--;
        position++;
      }
      if (depth != 0) return null;
      spaced = true;
      continue;
    }
    if (c == '"') {
      final value = StringBuffer();
      position++;
      var closed = false;
      while (position < text.length) {
        c = text[position++];
        if (c == '"') {
          closed = true;
          break;
        }
        if (c == '\\') {
          if (position == text.length) return null;
          c = text[position++];
        }
        value.write(c);
      }
      if (!closed) return null;
      tokens.add(Token('quoted', value.toString(), spaced));
    } else if (specials.contains(c)) {
      tokens.add(Token(c, c, spaced));
      position++;
    } else if (isWord(c)) {
      var end = position + 1;
      while (end < text.length && isWord(text[end])) {
        end++;
      }
      tokens.add(Token('word', text.substring(position, end), spaced));
      position = end;
    } else {
      return null;
    }
    spaced = false;
  }
  return tokens;
}

(String, bool, bool) decodeWord(String word) {
  if (word.length < 4 || !word.startsWith('=?') || !word.endsWith('?=')) {
    return (word, false, false);
  }
  final pieces = word.substring(2, word.length - 2).split('?');
  if (pieces.length != 3 || pieces.any((piece) => piece.isEmpty)) {
    return (word, false, false);
  }
  if (pieces[0].toLowerCase() != 'us-ascii') return (word, false, true);
  List<int>? data;
  if (pieces[1] == 'B' || pieces[1] == 'b') {
    data = strictBase64(pieces[2]);
  } else if (pieces[1] == 'Q' || pieces[1] == 'q') {
    data = <int>[];
    for (var position = 0; position < pieces[2].length;) {
      final c = pieces[2][position];
      if (c == '_') {
        data.add(32);
        position++;
      } else if (c == '=') {
        final value = escapedByte(pieces[2], position);
        if (value == null) return (word, false, true);
        data.add(value);
        position += 3;
      } else {
        data.add(c.codeUnitAt(0));
        position++;
      }
    }
  }
  if (data == null || data.any((c) => c < 32 || c > 126)) {
    return (word, false, true);
  }
  return (String.fromCharCodes(data), true, false);
}

(String, bool) decodeUnstructured(String value) {
  final output = StringBuffer();
  var previous = false;
  var error = false;
  final words = splitWords(value);
  for (var i = 0; i < words.length; i++) {
    final (text, decoded, failed) = decodeWord(words[i]);
    if (i > 0 && !(decoded && previous)) output.write(' ');
    output.write(text);
    previous = decoded;
    error = error || failed;
  }
  return (collapseWhitespace(output.toString()), error);
}

Parameters? parseParameters(String value, bool withSubtype) {
  final tokens = tokenize(value, true);
  if (tokens == null || tokens.isEmpty || tokens[0].kind != 'word') {
    return null;
  }
  final mainType = tokens[0].text.toLowerCase();
  var subtype = '';
  var position = 1;
  if (withSubtype) {
    if (tokens.length < 3 || tokens[1].kind != '/' || tokens[2].kind != 'word') {
      return null;
    }
    subtype = tokens[2].text.toLowerCase();
    position = 3;
  }
  final parameters = <String, String>{};
  while (position < tokens.length) {
    if (position + 3 >= tokens.length ||
        tokens[position].kind != ';' ||
        tokens[position + 1].kind != 'word' ||
        tokens[position + 2].kind != '=' ||
        !['word', 'quoted'].contains(tokens[position + 3].kind)) {
      return null;
    }
    parameters.putIfAbsent(tokens[position + 1].text.toLowerCase(),
        () => tokens[position + 3].text);
    position += 4;
  }
  return Parameters(mainType, subtype, parameters);
}

import 'dart:io';
import 'addresses.dart';
import 'dates.dart';
import 'headers.dart';
import 'mime.dart';
import 'threader.dart';

const checkedFields = [
  'From', 'To', 'Cc', 'Subject', 'Date', 'Message-ID', 'In-Reply-To',
  'References', 'MIME-Version', 'Content-Type', 'Content-Transfer-Encoding',
  'Content-Disposition'
];
const hiddenTags = ['head', 'style', 'script'];
const paragraphTags = [
  'p', 'div', 'ul', 'ol', 'table', 'tr', 'blockquote',
  'h1', 'h2', 'h3', 'h4', 'h5', 'h6'
];
const characterReferences = {
  'amp': '&', 'lt': '<', 'gt': '>', 'quot': '"', 'apos': "'", 'nbsp': ' '
};

List<String> readLines(String path) {
  final lines = File(path).readAsStringSync().split('\n');
  if (lines.isNotEmpty && lines.last.isEmpty) lines.removeLast();
  return lines;
}

List<List<MailLine>> readMailbox(String path) {
  final messages = <List<MailLine>>[];
  final lines = readLines(path);
  for (var i = 0; i < lines.length; i++) {
    var line = lines[i];
    if (line.startsWith('From ')) {
      messages.add([]);
      continue;
    }
    final unquoted = line.replaceFirst(RegExp(r'^>+'), '');
    if (unquoted != line && unquoted.startsWith('From ')) {
      line = line.substring(1);
    }
    if (messages.isNotEmpty) messages.last.add(MailLine(i + 1, line));
  }
  for (final lines in messages) {
    if (lines.isNotEmpty && lines.last.text.isEmpty) lines.removeLast();
  }
  return messages;
}

(List<MailLine>, List<MailLine>) splitSections(List<MailLine> lines) {
  final index = lines.indexWhere((line) => line.text.isEmpty);
  if (index < 0) return (lines, []);
  return (lines.sublist(0, index), lines.sublist(index + 1));
}

bool isMessageID(String text) {
  if (text.length < 3 || !text.startsWith('<') || !text.endsWith('>')) return false;
  final inside = text.substring(1, text.length - 1);
  if ('@'.allMatches(inside).length != 1 ||
      inside.startsWith('@') || inside.endsWith('@')) return false;
  return inside.codeUnits.every((c) =>
      c >= 33 && c <= 126 && !'<>()"\\'.contains(String.fromCharCode(c)));
}

List<String> extractIDs(String value) {
  final ids = <String>[];
  var position = 0;
  while (position < value.length) {
    final start = value.indexOf('<', position);
    if (start < 0) break;
    final end = value.indexOf('>', start + 1);
    if (end < 0) break;
    final id = value.substring(start, end + 1);
    if (isMessageID(id)) ids.add(id);
    position = end + 1;
  }
  return ids;
}

String dateNotation(int? date) => date == null ? 'invalid' : formatUTC(date);
String subjectNotation(String subject) => subject.isEmpty ? '(no subject)' : subject;
String dash(String text) => text.isEmpty ? '-' : text;

class Entity {
  final String number;
  var mainType = 'text';
  var subtype = 'plain';
  Map<String, String> parameters = {};
  String? disposition;
  String? filename;
  List<Entity>? children;
  var content = '';
  Entity(this.number);

  String parameter(String name) => parameters[name] ?? '';
}

class Message {
  final int number;
  final problems = <String>[];
  Mailbox? sender;
  List<String> to = [];
  List<String> cc = [];
  var subject = '';
  var baseSubject = '';
  var reply = false;
  int? date;
  var id = '';
  List<String> references = [];
  late Entity body;
  var thread = 0;
  var depth = 0;
  Message? parent;
  Message(this.number);

  void process(List<MailLine> lines, Map<String, int> knownIDs) {
    final (headerLines, bodyLines) = splitSections(lines);
    final header = parseFields(headerLines);
    for (final number in header.invalid) {
      problems.add('bad header line $number');
    }
    for (final name in checkedFields) {
      if (header.count(name) > 1) problems.add('duplicate $name');
    }
    final from = header.value('From');
    if (from == null) {
      problems.add('missing From');
    } else {
      final parsed = parseAddressList(from);
      if (parsed == null || parsed.$1.length != 1 || parsed.$1[0] is! Mailbox) {
        problems.add('bad From');
      } else {
        sender = parsed.$1[0] as Mailbox;
        if (parsed.$2) problems.add('bad encoded word in From');
      }
    }
    to = recipients(header.value('To'), 'To');
    cc = recipients(header.value('Cc'), 'Cc');
    final decoded = decodeUnstructured(header.value('Subject') ?? '');
    subject = decoded.$1;
    if (decoded.$2) problems.add('bad encoded word in Subject');
    baseSubject = subject;
    while (baseSubject.toLowerCase().startsWith('re:')) {
      baseSubject = baseSubject.substring(3).replaceFirst(RegExp(r'^ +'), '');
      reply = true;
    }
    final dateValue = header.value('Date');
    if (dateValue == null) {
      problems.add('missing Date');
    } else {
      final parsed = parseDate(dateValue);
      date = parsed.$1;
      if (parsed.$2.isNotEmpty) problems.add(parsed.$2);
    }
    final idValue = header.value('Message-ID');
    if (idValue == null) {
      problems.add('missing Message-ID');
    } else if (!isMessageID(idValue)) {
      problems.add('bad Message-ID');
    } else if (knownIDs.containsKey(idValue)) {
      problems.add('Message-ID already used by message ${knownIDs[idValue]}');
    } else {
      id = idValue;
      knownIDs[id] = number;
    }
    references = extractIDs(header.value('References') ?? '');
    final replies = extractIDs(header.value('In-Reply-To') ?? '');
    if (replies.isNotEmpty && (references.isEmpty || references.last != replies.first)) {
      references.add(replies.first);
    }
    final version = header.value('MIME-Version');
    var mime = false;
    if (version != null) {
      final text = removeComments(version);
      mime = text != null && text.replaceAll(RegExp(r'[ \t]'), '') == '1.0';
      if (!mime) problems.add('bad MIME-Version');
    }
    body = parseEntity('1', header, bodyLines, mime);
  }

  List<String> recipients(String? value, String name) {
    if (value == null) return [];
    final parsed = parseAddressList(value);
    if (parsed == null) {
      problems.add('bad $name');
      return [];
    }
    final result = <String>[];
    for (final address in parsed.$1) {
      switch (address) {
        case Mailbox():
          result.add(address.address);
        case Group():
          result.addAll(address.mailboxes.map((mailbox) => mailbox.address));
      }
    }
    if (parsed.$2) problems.add('bad encoded word in $name');
    return result;
  }

  Entity parseEntity(String number, Header header, List<MailLine> lines, bool mime) {
    final entity = Entity(number);
    final contentType = header.value('Content-Type');
    if (mime && contentType != null) {
      final parsed = parseParameters(contentType, true);
      if (parsed == null) {
        problems.add('bad Content-Type in part $number');
      } else {
        entity.mainType = parsed.mainType;
        entity.subtype = parsed.subtype;
        entity.parameters = parsed.values;
      }
    }
    final disposition = header.value('Content-Disposition');
    if (mime && disposition != null) {
      final parsed = parseParameters(disposition, false);
      if (parsed == null) {
        problems.add('bad Content-Disposition in part $number');
      } else {
        entity.disposition = parsed.mainType;
        entity.filename = parsed.values['filename'];
      }
    }
    if (entity.filename == null || entity.filename!.isEmpty) {
      entity.filename = entity.parameters['name'];
    }
    final charset = entity.parameters['charset'];
    if (entity.mainType == 'text' && charset != null && charset.toLowerCase() != 'us-ascii') {
      problems.add('unsupported charset "${charset.toLowerCase()}" in part $number');
    }
    if (mime && entity.mainType == 'multipart') {
      final boundary = entity.parameter('boundary');
      if (boundary.isNotEmpty) {
        splitMultipart(entity, lines, boundary);
        return entity;
      }
      problems.add('missing boundary in part $number');
    }
    final original = lines.map((line) => line.text).join('\n');
    final encoding = mime ? (header.value('Content-Transfer-Encoding') ?? '7bit').toLowerCase() : '7bit';
    if (encoding == 'base64') {
      final content = decodeBase64Body(original);
      if (content == null) problems.add('bad base64 in part $number');
      entity.content = content ?? '';
    } else if (encoding == 'quoted-printable') {
      final (content, error) = decodeQuotedPrintable(original);
      if (error) problems.add('bad quoted-printable in part $number');
      entity.content = content;
    } else {
      entity.content = original;
      if (!['7bit', '8bit', 'binary'].contains(encoding)) {
        problems.add('unknown encoding "$encoding" in part $number');
      }
    }
    return entity;
  }

  void splitMultipart(Entity entity, List<MailLine> lines, String boundary) {
    final parts = <List<MailLine>>[];
    var closed = false;
    for (final line in lines) {
      final text = stripTrailing(line.text);
      if (text == '--$boundary--') {
        closed = true;
        break;
      }
      if (text == '--$boundary') {
        parts.add([]);
      } else if (parts.isNotEmpty) {
        parts.last.add(line);
      }
    }
    if (parts.isEmpty) {
      problems.add('no parts in part ${entity.number}');
    } else if (!closed) {
      problems.add('unterminated multipart in part ${entity.number}');
    }
    entity.children = [];
    for (var i = 0; i < parts.length; i++) {
      final (headerLines, bodyLines) = splitSections(parts[i]);
      final header = parseFields(headerLines);
      for (final number in header.invalid) {
        problems.add('bad header line $number');
      }
      entity.children!.add(parseEntity('${entity.number}.${i + 1}', header, bodyLines, true));
    }
  }
}

List<Entity> collectTextParts(Entity entity, bool allowHTML) {
  if (entity.children == null) {
    if (entity.disposition == 'attachment' || entity.mainType != 'text') return [];
    if (entity.subtype == 'plain' || entity.subtype == 'html' && allowHTML) return [entity];
    return [];
  }
  if (entity.subtype == 'alternative') {
    for (final html in [false, true]) {
      for (final child in entity.children!) {
        final parts = collectTextParts(child, html);
        if (parts.isNotEmpty) return parts;
      }
    }
    return [];
  }
  return [for (final child in entity.children!) ...collectTextParts(child, allowHTML)];
}

class LogicalLine {
  final int depth;
  String text;
  bool flowing;
  LogicalLine(this.depth, this.text, [this.flowing = false]);
}

String quotePrefix(int depth) =>
    depth > 0 ? '${List.filled(depth, '>').join()} ' : '';

List<String> wrap(String text, String prefix) {
  final lines = <String>[];
  var current = '';
  for (final word in splitWords(text)) {
    if (current.isNotEmpty && current.length + 1 + word.length > 72) {
      lines.add('$prefix$current');
      current = word;
    } else if (current.isNotEmpty) {
      current += ' $word';
    } else {
      current = word;
    }
  }
  lines.add('$prefix$current');
  return lines;
}

List<String> flowedLines(String content, bool deleteSpace) {
  if (content.isEmpty) return [];
  final logical = <LogicalLine>[];
  for (final line in content.split('\n')) {
    var text = line.replaceFirst(RegExp(r'^>+'), '');
    final depth = line.length - text.length;
    if (text.startsWith(' ')) text = text.substring(1);
    final flowing = text.endsWith(' ') && text != '-- ';
    if (logical.isNotEmpty && logical.last.flowing && logical.last.depth == depth) {
      final previous = logical.last;
      if (deleteSpace) previous.text = previous.text.substring(0, previous.text.length - 1);
      previous.text += text;
      previous.flowing = flowing;
    } else {
      logical.add(LogicalLine(depth, text, flowing));
    }
  }
  return [for (final line in logical) ...wrap(line.text, quotePrefix(line.depth))];
}

String tagName(String text) =>
    RegExp(r'^[A-Za-z0-9]*').firstMatch(text)!.group(0)!.toLowerCase();

String replaceReferences(String text) {
  final output = StringBuffer();
  var position = 0;
  while (position < text.length) {
    String? replacement;
    var end = -1;
    if (text[position] == '&') {
      end = text.indexOf(';', position + 1);
      if (end >= 0) {
        final name = text.substring(position + 1, end);
        replacement = characterReferences[name];
        if (replacement == null && name.startsWith('#') && digits(name.substring(1), [1, 2, 3])) {
          final value = int.parse(name.substring(1));
          if (value >= 32 && value <= 126) replacement = String.fromCharCode(value);
        }
      }
    }
    if (replacement == null) {
      output.write(text[position++]);
    } else {
      output.write(replacement);
      position = end + 1;
    }
  }
  return output.toString();
}

List<String> htmlLines(String content) {
  final blocks = <LogicalLine>[];
  var depth = 0;
  var position = 0;
  var text = '';
  String? hide;
  while (position < content.length) {
    final close = content[position] == '<' ? content.indexOf('>', position + 1) : -1;
    if (close < 0) {
      if (hide == null) text += content[position];
      position++;
      continue;
    }
    var inside = content.substring(position + 1, close);
    position = close + 1;
    final endTag = inside.startsWith('/');
    if (endTag) inside = inside.substring(1);
    final name = tagName(inside);
    if (hide != null) {
      if (endTag && name == hide) hide = null;
    } else if (!endTag && hiddenTags.contains(name)) {
      hide = name;
    } else if (name == 'br' || name == 'li' && !endTag) {
      blocks.add(LogicalLine(depth, text));
      text = name == 'li' ? '* ' : '';
    } else if (paragraphTags.contains(name)) {
      blocks.addAll([LogicalLine(depth, text), LogicalLine(depth, '')]);
      text = '';
      if (name == 'blockquote') {
        if (!endTag) {
          depth++;
        } else if (depth > 0) {
          depth--;
        }
      }
    }
  }
  blocks.add(LogicalLine(depth, text));
  final lines = <String>[];
  for (final block in blocks) {
    text = collapseWhitespace(block.text.replaceAll('\n', ' '));
    text = replaceReferences(text).replaceFirst(RegExp(r'^ +'), '').replaceFirst(RegExp(r' +$'), '');
    if (text.isNotEmpty) {
      lines.addAll(wrap(text, quotePrefix(block.depth)));
    } else if (lines.isNotEmpty && lines.last.isNotEmpty) {
      lines.add('');
    }
  }
  while (lines.isNotEmpty && lines.last.isEmpty) {
    lines.removeLast();
  }
  return lines;
}

(String, List<String>) displayLines(Entity entity) {
  if (entity.subtype == 'html') return ('html', htmlLines(entity.content));
  if (entity.parameter('format').toLowerCase() == 'flowed') {
    return ('flowed', flowedLines(entity.content, entity.parameter('delsp').toLowerCase() == 'yes'));
  }
  return ('plain', entity.content.isEmpty ? [] : entity.content.split('\n'));
}

class ThreadEntry {
  final Container container;
  final String prefix;
  final int depth;
  ThreadEntry(this.container, this.prefix, this.depth);
}

class Thread {
  final int number;
  final Container root;
  final entries = <ThreadEntry>[];
  final messages = <Message>[];
  Thread(this.number, this.root) {
    walk(root, '', '', 0);
  }

  void walk(Container container, String prefix, String stem, int depth) {
    entries.add(ThreadEntry(container, prefix, depth));
    final message = container.message;
    if (message != null) {
      messages.add(message);
      message.thread = number;
      message.depth = depth;
      message.parent = container.parent?.message;
    }
    for (var i = 0; i < container.children.length; i++) {
      if (i < container.children.length - 1) {
        walk(container.children[i], '$stem+- ', '$stem|  ', depth + 1);
      } else {
        walk(container.children[i], '$stem`- ', '$stem   ', depth + 1);
      }
    }
  }

  List<String> report() {
    final depth = entries.map((entry) => entry.depth).reduce((a, b) => a > b ? a : b);
    final senders = messages.where((m) => m.sender != null).map((m) => m.sender!.address).toSet();
    final dates = messages.map((m) => m.date).whereType<int>().toList()..sort();
    final lines = <String>[
      'thread $number messages ${messages.length} depth $depth senders ${senders.length}',
      dates.isEmpty ? 'span -' : 'span ${formatUTC(dates.first)} .. ${formatUTC(dates.last)}',
      'subject ${subjectNotation(root.subject ?? rootSubject(root))}',
    ];
    for (final entry in entries) {
      lines.add('${entry.prefix}${containerNotation(entry.container)}');
    }
    return lines;
  }
}

String containerNotation(Container container) {
  final message = container.message;
  if (message != null) {
    return '[${message.number}] ${dateNotation(message.date)} '
        '${message.sender?.address ?? '-'} ${subjectNotation(message.subject)}';
  }
  return container.subject != null ? '[subject] ${container.subject}' : '[missing] ${container.id}';
}

String senderNotation(Mailbox? sender) {
  if (sender == null) return '-';
  return sender.name.isEmpty ? sender.address : '${sender.name} <${sender.address}>';
}

List<String> entityLines(Entity entity) {
  var line = 'part ${entity.number} ${entity.mainType}/${entity.subtype}';
  if (entity.children != null) {
    return [line, for (final child in entity.children!) ...entityLines(child)];
  }
  line += ' ${entity.content.length}';
  if (entity.disposition != null) line += ' ${entity.disposition}';
  if (entity.filename != null && entity.filename!.isNotEmpty) line += ' "${entity.filename}"';
  return [line];
}

List<String> messageReport(Message message) => [
  'message ${message.number}',
  'id ${dash(message.id)}',
  'date ${dateNotation(message.date)}',
  'from ${senderNotation(message.sender)}',
  'to ${dash(message.to.join(', '))}',
  'cc ${dash(message.cc.join(', '))}',
  'subject ${subjectNotation(message.subject)}',
  'refs ${dash(message.references.join(' '))}',
  'thread ${message.thread} depth ${message.depth} parent ${message.parent?.number ?? '-'}',
  ...entityLines(message.body),
];

List<String> bodyReport(String request, Map<String, Message> messages) {
  final lines = ['request $request'];
  final message = messages[request];
  if (message == null) return [...lines, 'not found'];
  final parts = collectTextParts(message.body, true);
  lines.add('message ${message.number} text parts ${parts.length}');
  for (final part in parts) {
    final (format, display) = displayLines(part);
    var quoted = 0;
    var signature = 0;
    for (var i = 0; i < display.length; i++) {
      final line = stripTrailing(display[i]);
      if (line.startsWith('>')) quoted++;
      if (line == '--') signature = display.length - i - 1;
    }
    lines.add('part ${part.number} $format lines ${display.length} quoted $quoted signature $signature');
    for (final text in display) {
      final line = stripTrailing(text);
      lines.add(line.isEmpty ? '|' : '| $line');
    }
  }
  return lines;
}

class SenderStats {
  final String address;
  var name = '';
  var count = 0;
  final threads = <int>{};
  int? first;
  int? last;
  SenderStats(this.address);

  void add(Message message) {
    count++;
    threads.add(message.thread);
    final date = message.date;
    if (date != null) {
      if (first == null || date < first!) first = date;
      if (last == null || date > last!) last = date;
    }
    if (message.sender!.name.isNotEmpty) name = message.sender!.name;
  }
}

String csvField(String text) => text.contains(',') || text.contains('"')
    ? '"${text.replaceAll('"', '""')}"' : text;

List<String> sendersReport(List<Message> messages) {
  final stats = <String, SenderStats>{};
  for (final message in messages) {
    final sender = message.sender;
    if (sender == null) continue;
    stats.putIfAbsent(sender.address, () => SenderStats(sender.address)).add(message);
  }
  final entries = stats.values.toList()..sort((a, b) {
    final countOrder = b.count.compareTo(a.count);
    return countOrder != 0 ? countOrder : a.address.compareTo(b.address);
  });
  return [
    'address,name,messages,threads,first,last',
    for (final entry in entries)
      '${entry.address},${csvField(entry.name)},${entry.count},${entry.threads.length},'
      '${entry.first == null ? '-' : formatUTC(entry.first!)},'
      '${entry.last == null ? '-' : formatUTC(entry.last!)}',
  ];
}

List<String> malformedReport(List<Message> messages) {
  final flagged = messages.where((message) => message.problems.isNotEmpty).length;
  final total = messages.fold<int>(0, (total, message) => total + message.problems.length);
  return [
    'messages ${messages.length} malformed $flagged problems $total',
    for (final message in messages)
      for (final problem in message.problems) 'message ${message.number}: $problem',
  ];
}

List<String> joinBlocks(Iterable<List<String>> blocks) {
  final lines = <String>[];
  for (final block in blocks) {
    if (lines.isNotEmpty) lines.add('');
    lines.addAll(block);
  }
  return lines;
}

void writeOutput(String name, List<String> lines) {
  File('output/$name').writeAsStringSync(lines.isEmpty ? '' : '${lines.join('\n')}\n');
}

void main() {
  final messages = <Message>[];
  final knownIDs = <String, int>{};
  final mailbox = readMailbox('input/mailbox.mbox');
  for (var i = 0; i < mailbox.length; i++) {
    messages.add(Message(i + 1)..process(mailbox[i], knownIDs));
  }
  final roots = buildThreads(messages);
  final threads = [for (var i = 0; i < roots.length; i++) Thread(i + 1, roots[i])];
  for (final message in messages) {
    final parent = message.parent;
    if (parent != null && message.date != null && parent.date != null && message.date! < parent.date!) {
      message.problems.add('dated before parent message ${parent.number}');
    }
  }
  final byID = {for (final message in messages) if (message.id.isNotEmpty) message.id: message};
  final requests = readLines('input/requests.txt');
  Directory('output').createSync(recursive: true);
  writeOutput('threads.txt', joinBlocks(threads.map((thread) => thread.report())));
  writeOutput('messages.txt', joinBlocks(messages.map(messageReport)));
  writeOutput('bodies.txt', joinBlocks(requests.map((request) => bodyReport(request, byID))));
  writeOutput('senders.csv', sendersReport(messages));
  writeOutput('malformed.txt', malformedReport(messages));
}

const base64Alphabet =
    'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

List<int>? strictBase64(String text) {
  if (text.length % 4 != 0) return null;
  var end = text.length;
  while (end > 0 && text[end - 1] == '=') {
    end--;
  }
  if (text.length - end >= 3) return null;
  final result = <int>[];
  var buffer = 0;
  var bits = 0;
  for (var i = 0; i < end; i++) {
    final value = base64Alphabet.indexOf(text[i]);
    if (value < 0) return null;
    buffer = (buffer << 6) | value;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      result.add(buffer >> bits);
      buffer &= (1 << bits) - 1;
    }
  }
  return result;
}

String? decodeBase64Body(String text) {
  final compact = text.replaceAll(RegExp(r'[ \t\n]'), '');
  final data = strictBase64(compact);
  if (data == null) return null;
  final content = String.fromCharCodes(data).replaceAll('\r\n', '\n');
  if (content.codeUnits.any(
      (c) => c != 9 && c != 10 && (c < 32 || c > 126))) {
    return null;
  }
  return content;
}

int hexValue(String c) {
  final value = c.codeUnitAt(0);
  if (value >= 48 && value <= 57) return value - 48;
  if (value >= 65 && value <= 70) return value - 55;
  if (value >= 97 && value <= 102) return value - 87;
  return -1;
}

int? escapedByte(String text, int position) {
  if (position + 2 >= text.length) return null;
  final a = hexValue(text[position + 1]);
  final b = hexValue(text[position + 2]);
  if (a < 0 || b < 0) return null;
  return a * 16 + b;
}

(String, bool) decodeQuotedPrintable(String text) {
  final output = StringBuffer();
  var error = false;
  final lines = text.split('\n');
  for (var i = 0; i < lines.length; i++) {
    var line = lines[i].replaceFirst(RegExp(r'[ \t]+$'), '');
    final soft = line.endsWith('=');
    if (soft) line = line.substring(0, line.length - 1);
    var position = 0;
    while (position < line.length) {
      final c = line[position];
      final decoded = c == '=' ? escapedByte(line, position) : null;
      if (decoded != null &&
          (decoded == 9 || decoded >= 32 && decoded <= 126)) {
        output.writeCharCode(decoded);
        position += 3;
      } else {
        output.write(c);
        error = error || c == '=';
        position++;
      }
    }
    if (!soft && i < lines.length - 1) output.write('\n');
  }
  return (output.toString(), error);
}

import 'main.dart' show Message;

class Container {
  final String id;
  Message? message;
  Container? parent;
  List<Container> children = [];
  String? subject;
  Container(this.id);

  bool ancestorOf(Container? other) {
    while (other != null) {
      if (identical(this, other)) return true;
      other = other.parent;
    }
    return false;
  }
}

void adopt(Container parent, Container child) {
  child.parent = parent;
  parent.children.add(child);
}

class Threader {
  final table = <String, Container>{};
  final containers = <Container>[];

  Container containerOf(String id) => table.putIfAbsent(id, () {
    final container = Container(id);
    containers.add(container);
    return container;
  });

  void add(Message message) {
    final container = message.id.isNotEmpty ? containerOf(message.id) : Container('');
    if (message.id.isEmpty) containers.add(container);
    container.message = message;
    final references = message.references.map(containerOf).toList();
    for (var i = 0; i + 1 < references.length; i++) {
      final current = references[i];
      final following = references[i + 1];
      if (following.parent == null && !following.ancestorOf(current)) {
        adopt(current, following);
      }
    }
    if (container.parent != null) {
      container.parent!.children.remove(container);
      container.parent = null;
    }
    if (references.isNotEmpty && !container.ancestorOf(references.last)) {
      adopt(references.last, container);
    }
  }
}

List<Container> prune(List<Container> containers, bool atRoot) {
  final result = <Container>[];
  for (final container in containers) {
    container.children = prune(container.children, false);
    if (container.message != null || atRoot && container.children.length >= 2) {
      result.add(container);
      continue;
    }
    for (final child in container.children) {
      child.parent = atRoot ? null : container.parent;
    }
    result.addAll(container.children);
  }
  return result;
}

int compareMessages(Message a, Message b) {
  if ((a.date == null) != (b.date == null)) return a.date == null ? 1 : -1;
  if (a.date != null && a.date != b.date) return a.date!.compareTo(b.date!);
  final idOrder = a.id.compareTo(b.id);
  return idOrder != 0 ? idOrder : a.number.compareTo(b.number);
}

Message containerKey(Container container) {
  if (container.message != null) return container.message!;
  var best = containerKey(container.children.first);
  for (final child in container.children.skip(1)) {
    final candidate = containerKey(child);
    if (compareMessages(candidate, best) < 0) best = candidate;
  }
  return best;
}

void sortContainers(List<Container> containers) {
  for (final container in containers) {
    sortContainers(container.children);
  }
  containers.sort((a, b) => compareMessages(containerKey(a), containerKey(b)));
}

String rootSubject(Container root) =>
    (root.message ?? root.children.first.message!).baseSubject;

List<Container> mergeBySubject(List<Container> roots) {
  final groups = <String, List<Container>>{};
  for (final root in roots) {
    final subject = rootSubject(root);
    if (subject.isNotEmpty) groups.putIfAbsent(subject, () => []).add(root);
  }
  final merged = roots.where((root) {
    final subject = rootSubject(root);
    return subject.isEmpty || groups[subject]!.length == 1;
  }).toList();
  for (final entry in groups.entries) {
    final group = entry.value;
    if (group.length < 2) continue;
    final missing = group.where((root) => root.message == null).toList();
    final originals = group.where((root) =>
        root.message != null && !root.message!.reply).toList();
    final Container target;
    if (missing.isNotEmpty) {
      target = missing.first;
    } else if (originals.length == 1) {
      target = originals.first;
    } else {
      target = Container('')..subject = entry.key;
    }
    for (final root in group) {
      if (identical(root, target)) continue;
      if (root.message != null) {
        adopt(target, root);
      } else {
        for (final child in root.children) {
          adopt(target, child);
        }
      }
    }
    merged.add(target);
  }
  return merged;
}

List<Container> buildThreads(List<Message> messages) {
  final threader = Threader();
  for (final message in messages) {
    threader.add(message);
  }
  var roots = prune(threader.containers.where((c) => c.parent == null).toList(), true);
  sortContainers(roots);
  roots = mergeBySubject(roots);
  sortContainers(roots);
  return roots;
}
